  "body": " A menu-based SimpleTextEditor application  import javax.swing.*; import java.awt.*; import java.awt.event.*; import java.util.*; public class SimpleTextEditor extends JFrame implements ActionListener{ private JMenuBar mBar = new JMenuBar(); \/\/ Create the menu bar private JMenu fileMenu, editMenu, cutsMenu; \/\/ Menu references and items private JMenuItem cutItem, copyItem, pasteItem, selectItem,recentcutItem; private JMenuItem quitItem, openItem, saveItem; \/\/ File items private JTextArea display = new JTextArea(); \/\/ Here's where the editing occurs private String scratchPad = \"\"; \/\/ Scratch pad for cut\/paste private ArrayList recentCuts = new ArrayList(); public SimpleTextEditor() { super(\"Simple Text Editor\"); \/\/ Set the window title this.getContentPane().setLayout(new BorderLayout()); this.getContentPane().add(\"Center\", display); this.getContentPane().add(new JScrollPane(display)); display.setLineWrap(true); this.setJMenuBar(mBar); \/\/ Set this program's menu bar initFileMenu(); \/\/ Create the menus initEditMenu(); } \/\/ SimpleTextEditer() private void initEditMenu() { editMenu = new JMenu(\"Edit\"); \/\/ Create the edit menu mBar.add(editMenu); \/\/ and add it to menu bar cutItem = new JMenuItem (\"Cut\"); \/\/ Cut item cutItem.addActionListener(this); editMenu.add(cutItem); copyItem = new JMenuItem(\"Copy\"); \/\/ Copy item copyItem.addActionListener(this); editMenu.add(copyItem); pasteItem = new JMenuItem(\"Paste\"); \/\/ Paste item pasteItem.addActionListener(this); editMenu.add(pasteItem); editMenu.addSeparator(); selectItem = new JMenuItem(\"Select All\"); \/\/ Select item selectItem.addActionListener(this); editMenu.add(selectItem); editMenu.addSeparator(); cutsMenu = new JMenu(\"Recent Cuts\"); \/\/ Recent cuts submenu editMenu.add(cutsMenu); } \/\/ initEditMenu() private void initFileMenu() { fileMenu = new JMenu(\"File\"); \/\/ Create the file menu mBar.add(fileMenu); \/\/ and add it to the menu bar openItem = new JMenuItem(\"Open\"); \/\/ Open item openItem.addActionListener( this ); openItem.setEnabled(false); fileMenu.add(openItem); saveItem = new JMenuItem(\"Save\"); \/\/ Save item saveItem.addActionListener(this); saveItem.setEnabled(false); fileMenu.add(saveItem); fileMenu.addSeparator(); \/\/ Logical separator quitItem = new JMenuItem(\"Quit\"); \/\/ Quit item quitItem.addActionListener(this); fileMenu.add(quitItem); } \/\/ initFileMenu() public void actionPerformed(ActionEvent e) { JMenuItem m = (JMenuItem)e.getSource();\/\/ Get selected menu item if ( m == quitItem ) { \/\/ Quit dispose(); } else if (m == cutItem) { \/\/ Cut the selected text scratchPad = display.getSelectedText(); \/\/ Copy text to scratchpad display.replaceRange(\"\", \/\/ and delete display.getSelectionStart(), \/\/ from the start of the selection display.getSelectionEnd()); \/\/ to the end addRecentCut(scratchPad); \/\/ Add the cut text to the cuts menu } else if (m == copyItem) { \/\/ Copy the selected text to the scratchpad scratchPad = display.getSelectedText(); } else if (m == pasteItem) { \/\/ Paste the scratchpad to the document at caret display.insert(scratchPad, display.getCaretPosition()); \/\/ position } else if ( m == selectItem ) { display.selectAll(); \/\/ Select the entire document } else { JMenuItem item = (JMenuItem)e.getSource(); \/\/ Default is cutsMenu scratchPad = item.getActionCommand(); \/\/ Put cut back in the scratchpad } } \/\/ actionPerformed() private void addRecentCut(String cut) { recentCuts.add(0,cut); cutsMenu.removeAll(); for (int k = 0; k < recentCuts.size(); k++) { JMenuItem item = new JMenuItem((String)recentCuts.get(k)); cutsMenu.add( item ); item.addActionListener(this); } } \/\/ addRecentCut() public static void main(String args[]) { SimpleTextEditor f = new SimpleTextEditor(); f.setSize(300, 200); f.setVisible(true); f.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE); } \/\/ main() } \/\/ SimpleTextEditor  "
